//! own classes build it (`tools/javaoracle_1_7_10/BiomeTable.java`).
//!
//! Generated by `tools/javaoracle_1_7_10/run.sh BiomeTable <grass.png> <foliage.png>`
//! (after `build.sh`): do not edit by hand. Regenerate when the era's biome
//! classes change.

use crate::biome::GrassModifier;

/// One `Biome` of the era's table, by its own id.
pub(crate) struct EraBiome {
    /// The era's id: the byte a chunk's `Biomes` array holds.
    pub id: u8,
    /// `Biome.name`, in registry form.
    pub name: &'static str,
    /// `Biome.temperature`, the era's own (negative in the cold taigas).
    pub temperature: f32,
    /// `Biome.downfall`.
    pub downfall: f32,
    /// `Biome$Height.baseHeight` and `heightModifier`.
    pub height: [f32; 2],
    /// `Biome.getSkyColor(temperature)`, 0xRRGGBB.
    pub sky: u32,
    /// `GrassColors.getColor` at the base climate; the swamp's own
    /// `0x6A7039`; the mesa's fixed `getGrassColor`.
    pub grass: u32,
    /// `FoliageColors.get` at the base climate; the swamp's and the mesa's
    /// fixed `getFoliageColor`.
    pub foliage: u32,
    /// How the grass colour moves with position (`Biome.getGrassColor`'s
    /// overrides; the swamp's and the roofed forest's).
    pub modifier: GrassModifier,
    /// `Biome.waterFogColor`: `LiquidBlock`'s underwater fog colour.
    pub water_fog: u32,
    /// `Biome.isCold()`: the biome snows.
    pub snowy: bool,
    /// `Biome.rainy` (`isRainy()` is false in a cold biome: it snows).
    pub rainy: bool,
    /// `Biome.isHumid()`: downfall above 0.85.
    pub humid: bool,
}

